    "western_bridge_ru": "От античных басен Эзопа до современных советов директоров притча о Гусыне, несущей золотые яйца, остаётся главным уроком баланса между сегодняшней прибылью и бережной защитой живого актива.",
    "western_bridge_en": "From Aesop's ancient Greece to Stephen Covey's modern boardrooms, 'The Goose That Laid the Golden Eggs' remains the ultimate parable on balancing today's harvest with tomorrow's living asset.",
