    "cel_rebenka": "Хозяевам было мало одного золотого яичка в день: они захотели получить всё в одну секунду и потеряли само чудо. Сказка учит: самые лучшие плоды достаются тому, кто умеет ждать, заботиться и благодарить!",
    "cel_roditelya": "Любая устойчивая система состоит из двух частей: самой «Гусыни» (актив, репутация, команда, здоровье, технология) и «Золотых яиц» (ежедневная выручка, прибыль, результат).",
    "klyuch_malym": "1. Терпение творит чудеса: По одному золотому яичку в день собирается целое царское сокровище. 2. Береги источник: Заботься о своём здоровье, друзьях и знаниях, чтобы они радовали тебя долгие годы. 3. Умей благодарить: Кто радуется малому и говорит «спасибо», у того счастье умножается.",
    "klyuch_bolshim": "1. Не торопите рост: Детский талант созревает от ежедневной любви и регулярности, а не от штурмовщины. 2. Берегите силы семьи: Сон, здоровье и тёплые отношения важнее любой сиюминутной гонки. 3. Закон сложного процента: Маленький правильный шаг каждый день всегда побеждает нетерпеливую жадность.",
    "klyuch_malym_en": "",
    "klyuch_bolshim_en": "",
    "predislovie_ru": "От античных басен Эзопа до современных советов директоров притча о Гусыне, несущей золотые яйца, остаётся главным уроком баланса между сегодняшней прибылью и бережной защитой живого актива. Мы живём в век мгновенных удовольствий, когда ребёнку (да нередко и взрослому) хочется получить всё и сразу: съесть всю коробку конфет за один присест, потратить все карманные деньги в первый же час или бросить музыку и спорт, если не получилось стать чемпионом за одну неделю. Древняя сказка о Гусыне, несущей золотые яйца, даёт ребёнку удивительно глубокий ключ к счастливой жизни: самые главные сокровища: здоровье, талант, знания, верная дружба и семейный достаток: растут день за днём и требуют любви и терпения.",
