        "tekst_ru": "Жили-были в одной деревне крестьянин со своею женой. Жили они небогато, трудились от зари до зари, но часто сетовали на свою долю да мечтали о том, как бы разбогатеть в одночасье без долгого труда.\n\nВот однажды поехал хозяин на осеннюю ярмарку, продал мешок зерна и купил на вырученные гроши белую гусыню с золотистым пёрышком на крыле. Принёс её домой, устроил в тёплом углу за печкой плетёную корзинку с мягкой соломой и насыпал горсть отборного овса.",
        "img": "img/scenes/b5_s1.jpg?v=20261027v4"
