        "tekst_ru": "На следующее утро проснулся хозяин с первыми петухами, заглянул в корзинку за печкой: да так и ахнул! Лежит на чистой соломе яичко, да не простое, а литое, тяжёлое, из самого чистого червонного золота, и горит на утреннем солнышке, словно маленький жаркий уголёк.\n\nПодумал сперва крестьянин, уж не шутка ли это, отнёс яичко в город золотых дел мастеру, а тот взвесил его на весах и отсыпал за него целый кошель серебряных да золотых монет! На другое утро гусыня снесла ещё одно золотое яйцо, а на третье: ещё одно.",
        "img": "img/scenes/b5_s2.jpg?v=20261027v4"
