        "aforizm_ru": "❧ Лист III. Полные сундуки и неблагодарное сердце ❧",
        "tekst_ru": "Пошла у крестьянина с женой совсем другая жизнь. Справили они новый просторный дом с резным крыльцом, накупили добрых коней, бархатных кафтанов да кованых сундуков. Казалось бы: живи в радости, береги чудесную птицу, корми её отборным зерном да благодари Бога за ежедневный достаток!\n\nНо чем полнее становились их сундуки, тем сильнее разгоралась в их сердцах ненасытная жадность. Перестало им хватать одного золотого яичка в день: показалось им, что гусыня выдаёт богатство слишком медленно, по капле.",
