        "tekst_ru": "Однажды вечером сели муж с женой при свечах считать монеты, и зашептал хозяин с горящими от алчности глазами: «Послушай-ка, жена! Если эта гусыня каждое утро несёт по золотому яйцу, значит, у неё внутри спрятана целая золотая гора! Чего ради мы ждём милости по одному яичку в сутки? Давай-ка достанем всё золото разом!»\n\nЗакивала жадная хозяйка, затуманился у обоих разум от нетерпения. Забыли они, что живое чудо живёт только до тех пор, пока о нём заботятся с любовью и бережностью.",
