    "western_bridge_ru": "Родной брат европейского «Пряничного человечка» и басни Эзопа о Вороне и Лисице, сказка «Колобок»: лучший урок для детей и руководителей о том, как сладкая лесть усыпляет бдительность после первых побед.",
    "western_bridge_en": "Cousin to the Western 'Gingerbread Man' and Aesop's 'The Fox and the Crow', the classic tale of 'Kolobok' is a masterclass for both children and executives on how flattery blinds the overconfident, and how grounded vigilance keeps us safe.",
