        "tekst_ru": "Жили-были старик со старухой. Вот однажды и просит старик ласково: «Испеки-ка мне, старая, румяный колобок!»: «Да из чего печь-то? Муки ведь в ларе не осталось!»: «Эх, старушка! По амбару помети, по сусекам поскреби: вот и наберётся горсти две!»\n\nВзяла старушка гусиное крылышко, по амбару помела, по сусекам поскребла и набрала муки пригоршни две. Замесила тесто на густой сметане, скатала круглый колобок, изжарила его в топлёном масле да и положила на резное окошко простынуть.",
