        "tekst_ru": "Полежал Колобок на окошке, на солнышко поглядел, да и надоело ему смирно лежать: покатился он с окна на лавку, с лавки на пол, по полу к дверям, прыг через порог, в сени, из сеней на крыльцо, с крыльца на широкий двор, а со двора за ворота: дальше и дальше в зелёный лес!\n\nКатится Колобок по лесной дороге, а навстречу ему Косой Заяц бежит: «Колобок, Колобок! Я тебя съем!»: «Не ешь меня, Косой Зайчик, я тебе песенку спою: я Колобок, Колобок, по амбару метён, по сусекам скребён, на сметане мешён, в печку сажён, на окошке стужён! Я от дедушки ушёл, я от бабушки ушёл, а от тебя, Зайца, и подавно уйду!», и покатился себе дальше!",
