        "tekst_ru": "Катится Колобок по тропинке, а навстречу ему из чащи серый Волк выходит: «Колобок, Колобок, я тебя съем!». Запел Колобок свою хвастливую песенку: как от дедушки ушёл, от бабушки ушёл, от зайца ушёл, и от Волка укатился, только Волк его и видел!\n\nКатится дальше по сосновому бору, а навстречу ему косолапый Медведь идёт, хворост ломает, кусты к земле гнёт: «Колобок, Колобок, я тебя съем!»: «Где тебе, косолапому, съесть меня!»: засмеялся Колобок, пропел ему свою песню и ещё быстрее покатился по дорожке, думая, что теперь ему в целом свете никто не страшен.",
