        "tekst_ru": "Катится Колобок по солнечной полянке, а навстречу ему идёт Лиса Патрикеевна: поступь мягкая, шубка пушистая, глаза ласковые: «Здравствуй, Колобок! Какой же ты пригожий, румяный да душистый!»\n\nОбрадовался Колобок такой похвале, загордился ещё пуще и тут же запел свою любимую песню про то, как от дедушки, бабушки, зайца, волка и медведя ушёл. А Лисица слушает, головку набок склонила да ласково так приговаривает: «Ах, песенка какая славная! Да вот беда, голубчик: стара я стала, плохо слышу. Сядь-ка ко мне на носок да пропой ещё разок, погромче!»",
