    "western_bridge_ru": "Родственная европейской сказке братьев Гримм «Золотая птица» и великим восточным эпосам о верных спутниках, история Ивана-царевича и Серого Волка учит искусству стратегического союза, дисциплины и верности дружине.",
    "western_bridge_en": "Sharing its mythic roots with the Brothers Grimm's 'The Golden Bird' and the great Eastern epics of loyal companions, 'Tsarevich Ivan and the Grey Wolf' teaches the timeless art of mentorship, discipline, and strategic alliance.",
