        "aforizm_ru": "❧ Глава I (Лист 2). Ошибка у золотой клетки: когда блеск ослепляет разум ❧",
        "tekst_ru": "Домчал Серый Волк царевича быстрее ветра до белокаменных палат царя Афрона и строго-настрого наказал ему у стены: «Перелезь через ограду, Иван-царевич: сторожа все крепко спят. Возьми в тереме Жар-птицу, да смотри: золотую клетку ни за что не трогай, не то беды не миновать!»\n\nВошёл Иван-царевич в палаты, взял чудесную Жар-птицу в руки, да разгорелись у него глаза на клетку из чистого золота с самоцветами: «Ах, какая красота! Как же я такую птицу да без золотой клетки понесу?». Только протянул руку к клетке, загремели по всему саду гусли да колокола, проснулась стража и схватила царевича! А царь Афрон велел: «Добудешь мне у царя Кусмана Златогривого коня: прощу и отдам Жар-птицу!»",
        "img": "img/scenes/b8_s2.jpg?v=20261027v4"
