        "aforizm_ru": "❧ Глава III (Лист 4). Мудрый шаг Серого Волка и возвращение с победой ❧",
        "tekst_ru": "Глава III. Вздохнул Серый Волк и говорит: «Опять ты моего слова не послушался, Иван-царевич! Видно, в третий раз мне самому идти надо». Велел он царевичу ждать у зелёного дуба за городом, а сам перемахнул через золотую решётку в заповедный сад, дождался, когда Елена Прекрасная выйдет гулять с нянюшками, и умчал её вместе с Иваном-царевичем.\n\nА по дороге назад перекинулся мудрый Серый Волк сперва Еленой Прекрасной, а затем и Златогривым конём: так смекалкой да верной дружбой помог он Ивану-царевичу и слово перед царями сдержать, и все сокровища сохранить, и с невестой Еленой Прекрасной в родное царство отправиться.",
