        "tekst_ru": "Доехал Иван-царевич до родных рубежей, тепло простился с Серым Волком и прилёг отдохнуть в чистом поле под шатром. Тут наехали на него старшие братья, позавидовали чёрной завистью его богатырской добыче, погубили брата, а Жар-птицу, коня и Елену Прекрасную забрали себе, строго пригрозив ей не открывать правду отцу.\n\nНо почуял беду верный Серый Волк, прибежал в чистое поле, добыл у старого ворона живой и мёртвой воды и оживил Ивана-царевича! Промчал он друга прямо во дворец в самый час свадьбы: бросилась Елена Прекрасная к своему настоящему жениху, открылась вся правда перед царём Берендеем, а Иван-царевич на всю жизнь запомнил три великих урока Серого Волка.",
