    "cel_roditelya": "Перед нами гениальная формула созидания и продаж: как превратить холодное «у нас нет бюджета» в горячее соучастие партнёра.",
    "klyuch_malym": "1. Смекалка сильнее обиды: Умный и весёлый человек найдёт выход там, где другой расплачется. 2. Начни с малого шага: Любое большое дело складывается по горсточке: сначала вода, потом соль и крупа. 3. Будь щедрым: Делиться с другими: самая большая радость для сердца.",
