    "klyuch_malym_en": "",
    "klyuch_bolshim_en": "",
    "predislovie_ru": "Известная во всём мире как «Суп из камня» (Stone Soup), сказка «Каша из топора»: лучший учебник созидательного лидерства о том, как одна живая инициатива превращает закрытый дефицит в общее изобилие. Что делать, если тебя встретили неприветливо, пожадничали или отказались делиться игрушками? Обычный ответ: обидеться, заплакать или вступить в ссору, после которой всем станет только хуже. Но русская сказка «Каша из топора» показывает совершенно другой, победный путь! Бывалый солдат не ругает скупую старуху и ничего не требует силой. Он с доброй улыбкой затевает вокруг простого топора такую увлекательную игру, что хозяйка сама забывает о своей скупости, с радостью приносит соль, крупу и масло и садится с гостем за один тёплый стол.",
