        "tekst_ru": "Шёл служивый солдат в побывку домой. Долго шёл по пыльной дороге, притомился на солнцепёке и крепко проголодался. Дошёл до деревни, постучал в крайнюю богатую избу: «Здравствуй, божья старушка! Пусти служивого отдохнуть с дороги да дай хоть корочку хлеба перекусить!»\n\nА старуха была зажиточная, полны сусеки да погреба всякого добра, да скупая-прескупая! Прикинулась она бедной сиротой, заохала да запричитала: «Ступай, добрый человек, в другую избу: у меня у самой дома ни крошечки нет, со вчерашнего дня ничего не ела!»",
