        "tekst_ru": "Кипит вода в чугунке, булькает, пар под потолок поднимается, а старуха глаз с котла не сводит: так ей любопытно! Достал солдат деревянную ложку, помешал варево, попробовал, причмокнул и говорит: «Эх, до чего же навариста каша выходит! Скоро совсем поспеет, вот только бы посолить её чуточку!»\n\nСтаруха тут же отозвалась: «Соль-то у меня есть, посоли, служивый!». Посолил солдат воду, снова попробовал и качает головой: «Ну, теперь совсем бы царская была каша, кабы в неё хоть малую горсточку крупы бросить!»",
