    "klyuch_malym": "1. Своё дело в доме: Дружба крепнет там, где каждый помогает общему дому. 2. Береги чужой труд: Сила хороша тогда, когда она строит, а не давит крышу. 3. Не плачь над поломкой: Дружные руки всегда построят новый дом лучше старого.",
