    "predislovie_ru": "Родная сестра европейской «Рукавички», сказка «Теремок» показывает и семьям, и быстрорастущим компаниям, почему широкое гостеприимство обязательно должно опираться на расчёт прочности стен и своевременное обновление дома. Сказка «Теремок»: первая в жизни ребёнка энциклопедия семейного уклада и командной дружбы. Посмотрите, какой важный вопрос звучит у порога: «А ты кто?»: то есть чем ты можешь порадовать и поддержать наш общий дом? Мышка зерно толчёт, Лягушка воду носит, Зайчик дрова рубит, Лисичка пироги печёт, а Волчок двор бережёт. А когда огромный Медведь по неосторожности садится на маленькую крышу и старый теремок рассыпается, звери не разбегаются в обиде, а вместе с тем же Медведем строят новый, просторный Терем! Это чудесный урок для всей семьи.",
