        "tekst_ru": "Стоит в чистом поле резной расписной теремок: он не низок, не высок. Бежала мимо Мышка-норушка, увидела теремок, остановилась у крылечка и спрашивает звонко: «Терем-теремок! Кто в тереме живёт?». Никто не отзывается. Вошла Мышка в теремок и стала в нём жить-поживать.\n\nПрискакала к теремку Лягушка-квакушка, за ней прибежал Зайчик-побегайчик: «Терем-теремок! Кто в тереме живёт?»: «Я, Мышка-норушка! Я, Лягушка-квакушка! А ты кто?»: «А я Зайчик-побегайчик!»: «Иди к нам жить!». Стали они жить втроём: дружно да весело.",
