        "tekst_ru": "Бежит мимо Лисичка-сестричка, постучала в резное окошко: «Терем-теремок! Кто в тереме живёт?». Пустили добрые звери и Лисичку-сестричку. А следом прибежал Волчок-серый бочок, и ему место у тёплой печки нашлось!\n\nЖивут они впятером в расписном теремке, песни поют да хозяйство ведут слаженно, без лени: Мышка зерно толчёт, Лягушка воду носит да пол метёт, Зайчик дрова рубит, Лисичка румяные пироги печёт, а Волчок двор сторожит да порядок бережёт.",
        "img": "img/scenes/b12_s2.jpg?v=20261027v4"
