        "tekst_ru": "Слава о дружном лесном теремке разнеслась по всему сосновому бору: в доме тепло, медный самовар кипит, пирогами пахнет, никто ни с кем не ссорится! Всяк своё место знает и общему делу рад.\n\nВот и прослышал про весёлый теремок огромный косолапый Медведь. Захотелось и ему к дружной компании примкнуть: пошёл он прямиком через лес, сучья под тяжёлыми лапами трещат, земля гудит.",
