        "tekst_ru": "Подошёл Медведь к теремку да как заревёт во всю мочь: «Терем-теремок! Кто в тереме живёт?». Ответили ему Мышка, Лягушка, Зайчик, Лисичка и Волчок, да и позвали по доброте душевной: «Иди к нам жить!»\n\nПолез Медведь в двери: не лезет! Полез в окошко: никак не помещается! И говорит он тогда: «А я лучше у вас на крыше буду жить!»: «Да ты нас раздавишь!»: «Нет, не раздавлю!». Влез Медведь на крышу и только уселся, трах-тарарах!: затрещал теремок, покосился и рассыпался по брёвнышку!",
