    "subtitle_ru": "Классическая русская сказка о рыбаке и Золотой рыбке с беседами для детей о благодарности, чувстве меры и доброте к близким и практическими советами для родителей",
    "en_title_family": "The Fisherman and the Golden Fish: Gratitude, Enoughness, and Wise Wishes",
    "en_title_exec": "The Fisherman and the Golden Fish: Scope Creep, Risk Appetite, and Leadership Backbone",
    "western_bridge_ru": "Восходящая к европейскому сюжету братьев Гримм «О рыбаке и его жене» и шедевру А. С. Пушкина 1833 года, «Сказка о рыбаке и рыбке»: величайшая мировая притча о чувстве меры, границах требований и мужестве вовремя сказать «Достаточно».",
    "western_bridge_en": "Sharing its ancient roots with the Brothers Grimm's 'The Fisherman and His Wife' and Alexander Pushkin's 1833 masterpiece, 'The Fisherman and the Golden Fish' is the world's sharpest parable on greed, boundaries, and the courage to say 'Enough'.",
