    "cover_mgmt": "img/covers/b13_mgmt.jpg?v=20261027v4",
    "cel_rebenka": "Золотая рыбка с радостью подарила и новое корыто, и светлую избу, и терем, но старуха ни разу не сказала «спасибо» и захотела сделать саму рыбку своей служанкой. Жадность и грубость всегда оставляют человека у разбитого корыта!",
    "cel_roditelya": "Сказка с математической точностью описывает отношения между создателем контакта («Стариком»), внутренним потребителем ресурсов («Старухой») и рыночной средой («Синим морем и Золотой рыбкой»).",
    "klyuch_malym": "1. Сила слова «спасибо»: Благодарному сердцу мир дарит чудеса, а жадному оставляет пустоту. 2. Знай добрую меру: Умей вовремя остановиться и порадоваться тому, что у тебя есть. 3. Береги своих близких: Никакие короны не заменят любви и уважения к родным людям.",
    "klyuch_bolshim": "1. Любовь с границами: Не превращайтесь в безропотного старика перед детскими капризами. 2. Лекарство от пресыщения: Изобилие без благодарности разрушает характер ребёнка. 3. Уважение к старшим: Иерархия любви и почтения в семье: основа жизненного благополучия.",
    "klyuch_malym_en": "",
    "klyuch_bolshim_en": "",
    "predislovie_ru": "Восходящая к европейскому сюжету братьев Гримм «О рыбаке и его жене» и шедевру А. С. Пушкина 1833 года, «Сказка о рыбаке и рыбке»: величайшая мировая притча о чувстве меры, границах требований и мужестве вовремя сказать «Достаточно». Выражение «остаться у разбитого корыта» знает каждый человек в нашей стране. Но задумайтесь вместе с ребёнком: почему старуха, получившая от Золотой рыбки и новое корыто, и светлую избу, и боярский терем, и даже царский венец, так ни одной минуты не улыбнулась и не была счастлива? Потому что без благодарности в сердце и без любви к близким никакие подарки мира не приносят радости! Эта сказка учит ребёнка двум золотым качествам: искренне говорить «спасибо» за каждое добро и беречь уважение к тем, кто рядом.",
