        "tekst_ru": "Жил старик со своею старухой у самого синего моря. Они жили в ветхой землянке ровно тридцать лет и три года: старик ловил неводом рыбу, старуха пряла свою пряжу. Раз он в море закинул невод: пришёл невод с одною тиной. Он в другой раз закинул невод: пришёл невод с травой морскою. В третий раз закинул он невод: пришёл невод с одною рыбкой, с непростою рыбкой: золотою!\n\nКак взмолится золотая рыбка человечьим голосом: «Отпусти ты, старче, меня в море! Дорогой за себя дам откуп: откуплюсь чем только пожелаешь!». Удивился старик, ласково сказал ей: «Бог с тобою, золотая рыбка! Твоего мне откупа не надо; ступай себе в синее море, гуляй там себе на просторе!», и пустил рыбку в волну.",
        "img": "img/scenes/b13_s1.jpg?v=20261027v4"
