        "tekst_ru": "И избы старухе показалось мало! Кричит она старику: «Не хочу быть чёрною крестьянкой, хочу быть столбовою дворянкой!». Пошёл старик к синему морю: неспокойно синее море! Исполнила рыбка и это желание.\n\nВоротился старик, видит: высокий терем. На крыльце стоит его старуха в дорогой собольей душегрейке, парчовая на маковке кичка, жемчуги огрузили шею, на руках золотые перстни, на ногах красные сапожки. Перед нею усердные слуги: она бьёт их, за чупрун таскает, а родного мужа на конюшню служить посылает!",
