        "tekst_ru": "Через неделю вздурилась старуха ещё пуще: «Не хочу быть столбовою дворянкой, а хочу быть вольною царицей!». Почернело синее море, но сделала рыбка старуху и царицей. Сидит она в царских палатах за столом, бояре да дворяне ей служат, заморские вина наливают, грозная стража с топориками у дверей стоит.\n\nПоклонился старик царице в ноги, а она и глядеть на него не захотела: велела гнать его взашей с царского двора! Но и царского венца ей стало мало.",
