        "tekst_ru": "Вскоре пришёл взглянуть на ткань и сам король со всей придворной свитой. Глянул король на пустой станок, и у него замерло сердце: «Что за притча! Я ничего не вижу! Неужели я глуп и не достоин быть королём?!»\n\nИ чтобы никто ничего не заподозрил, король важно закивал головой и воскликнул: «О, это бесподобно! Высшее одобрение!». А все царедворцы смотрели на пустые станки, ничего не видели, но наперебой поддакивали королю и советовали непременно надеть новое платье на праздничное шествие!",
