        "tekst_ru": "В день праздника обманщики сделали вид, будто облачают короля в невидимые одежды, а камергеры с важным видом подняли с пола воздух, словно несли длинный шлейф мантии. Вышел король под роскошным балдахином на главную площадь, и все горожане из страха показаться глупцами громко кричали: «Какой бесподобный наряд! Какой дивный шлейф!»\n\nКак вдруг маленький мальчик с чистым сердцем звонко крикнул: «Да ведь на короле ничего нет! А король-то голый!». И тут весь народ зашумел: «Мальчик говорит правду: король-то голый!». Понял король, что его провели, но из ложной гордости ещё выше задрал нос, а свита продолжала нести за ним несуществующий шлейф.",
